window.AUTH=window.AUTH||{};window.AUTH["19-267"]={"d":"19-267","id":"2019/19-267","n":"Our Lady of Guadalupe School v. Morrissey-Berru","briefs":[{"k":"petitioner","label":"Brief of petitioner Our Lady of Guadalupe School","date":"2020-02-03","url":"https://www.supremecourt.gov/DocketPDF/19/19-267/130838/20200203182150600_OLG%20Opening%20brief_FINAL.pdf","side":"pet","n":53},{"k":"united-states","label":"Brief amicus curiae of United States Conference of Catholic Bishops","date":"2020-02-10","url":"https://www.supremecourt.gov/DocketPDF/19/19-267/132539/20200210155906397_19-267%20and%2019-348%20tsac%20USCCB.pdf","side":"us","n":19},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2020-02-10","url":"https://www.supremecourt.gov/DocketPDF/19/19-267/132592/20200210211341842_19-267%2019-348tsacUnitedStates.pdf","side":"us","n":17},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2020-02-10","url":"https://www.supremecourt.gov/DocketPDF/19/19-267/132688/20200211161548810_19-26719-348tsacUnitedStates.pdf","side":"us","n":17},{"k":"respondent","label":"Brief of respondents","date":"2020-03-04","url":"https://www.supremecourt.gov/DocketPDF/19/19-267/135072/20200304162829192_19-267%20and%2019-348%20bs.pdf","side":"res","n":71},{"k":"reply","label":"Reply of petitioners","date":"2020-04-03","url":"https://www.supremecourt.gov/DocketPDF/19/19-267/140800/20200403111628542_19-267_19-348%20Reply%20Brief%20For%20Petitioners.pdf","side":"pet","n":52}],"opinion":"https://www.supremecourt.gov/opinions/preliminaryprint/591US2PP_web.pdf#page=291","tr":true,"items":[{"t":"case","label":"Archdiocese of Washington v. Moersen","cite":"925 A.2d 659","y":2007,"court":"Md.","url":"https://www.courtlistener.com/c/A.2d/925/659/","by":{"0":"35"}},{"t":"case","label":"Bouldin v. Alexander","cite":"82 U.S. 131","y":1872,"id":"scdb/1872-038","sc":1,"sum":"From about the 1st of September, 1857, a small number of colored persons were in the habit of eonsociating in prayer-meetings and other religious conferences at the house of one Albert Bouldin, a colored man from Virginia, who had been licensed to preach, and was so styled the Reverend Albert Bouldin; he being always a chief actor in the assemblages. The persons were, at first, few in number, feeble in resources, …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"30"}},{"t":"case","label":"Cannata v. Catholic Diocese of Austin","cite":"700 F.3d 169","y":2012,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/700/169/","by":{"0":"39","2":"14","3":"14","5":"3, 13"}},{"t":"case","label":"Catholic Charities of Sacramento, Inc. v. Superior Court","cite":"85 P.3d 67","y":2004,"court":"Cal.","url":"https://www.courtlistener.com/c/P.3d/85/67/","by":{"0":"35"}},{"t":"case","label":"Cha v. Korean Presbyterian Church","cite":"553 S.E.2d 511","y":2001,"court":"Va.","url":"https://www.courtlistener.com/c/S.E.2d/553/511/","by":{"0":"35"}},{"t":"case","label":"Colorado Christian Univ. v. Weaver","cite":"534 F.3d 1245","y":2008,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/534/1245/","op":1,"by":{"0":"39"}},{"t":"case","label":"Conlon v. InterVarsity Christian Fellowship","cite":"777 F.3d 829","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/777/829/","by":{"0":"40"}},{"t":"case","label":"Corporation of the Presiding Bishop of the Church of Jesus Christ of Latterday Saints v. Amos","cite":"483 U.S. 327","y":1987,"id":"1986/86-179","sc":1,"sum":"To be valid, the state action must first promote a \"secular legislative purpose.\" The Court found that Section 702 satisfied this criterion, since it ensured that the government would not determine for religious organizations what they could count as religious activities.","sumSrc":"Oyez","by":{"0":"4, 25","1":"13","2":"20","3":"20","4":"30"}},{"t":"case","label":"Coulee Catholic Sch. v. Labor and Indus. Review Comm’n","cite":"768 N.W.2d 868","y":2009,"court":"Wis.","url":"https://www.courtlistener.com/c/N.W.2d/768/868/","by":{"0":"35","5":"9"}},{"t":"case","label":"vi Curay-Cramer v. Ursuline Academy","cite":"450 F.3d 130","y":2006,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/450/130/","by":{"0":"33","4":"51"}},{"t":"case","label":"Dayner v. Archdiocese of Hartford","cite":"23 A.3d 1192","y":2011,"court":"Conn.","url":"https://www.courtlistener.com/c/A.3d/23/1192/","by":{"0":"35","5":"9"}},{"t":"case","label":"EEOC v. R.G. &. G.R. Harris Funeral Homes, Inc.","cite":"884 F.3d 560","y":2018,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/884/560/","by":{"0":"44"}},{"t":"case","label":"El-Farra v. Sayyed","cite":"226 S.W.3d 792","y":2006,"court":"Ark.","url":"https://www.courtlistener.com/c/S.W.3d/226/792/","by":{"0":"34-35"}},{"t":"case","label":"Employment Div. v. Smith","cite":"494 U.S. 872","y":1990,"id":"1989/88-1213","sc":1,"op":5,"sum":"The Court held that the First Amendment does not protect individuals engaging in illegal acts as part of a religious ceremony.","sumSrc":"Oyez","by":{"0":"28","4":"51"}},{"t":"case","label":"Fratello v. Archdiocese of New York","cite":"863 F.3d 190","y":2017,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/863/190/","sum":"Explaining that relying excessively on titles and credentials “penalize[s] religious groups for allowing laypersons to participate in their ministries”.","sumSrc":"brief:1","by":{"0":"2, 39, 40","1":"13, 14","2":"14","3":"14","5":"passim"}},{"t":"case","label":"German Reformed Church v. Commonwealth ex rel. Seibert","cite":"3 Pa. 282","y":1846,"court":"Pa.","url":"https://www.courtlistener.com/c/Pa./3/282/","by":{"0":"30"}},{"t":"case","label":"Gonzalez v. Roman Catholic Archbishop of Manila","cite":"280 U.S. 1","y":1929,"id":"scdb/1929-001","sc":1,"sum":"1. A judgment of the Supreme Court of the Ph,ippine Islands in a case in which the amount in controversy exccedA $25,000, is reviewable by this Court on certiorari.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30, 51","2":"13, 31","3":"13, 31"}},{"t":"case","label":"Hosanna-Tabor Evangelical Lutheran Church & Sch. v. EEOC","cite":"565 U.S. 171","y":2011,"id":"2011/10-553","sc":1,"op":22,"sum":"The Court found that a woman employed by a religious school who taught daily religion classes, was a commissioned minister, and regularly lead students in prayer and worship, did not have grounds to sue the school under the Ministerial Exception.","sumSrc":"Oyez","by":{"0":"passim, 21","1":"passim","2":"passim","3":"passim","4":"passim","5":"passim"}},{"t":"case","label":"Kedroff v. St. Nicholas Cathedral of Russian Orthodox Church","cite":"344 U.S. 94","y":1952,"id":"scdb/1952-013","sc":1,"op":3,"sum":"As thus construed and applied, the New York statute interferes with the free exercise of religion, contrary to the-First Amendment, made applicable to the states by the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"4, 24, 28, 37","2":"12, 18, 32, 33","3":"12, 18, 32, 33","4":"28"}},{"t":"case","label":"vii Kirby v. Lexington Theological Seminary","cite":"426 S.W.3d 597","y":2014,"court":"Ky.","url":"https://www.courtlistener.com/c/S.W.3d/426/597/","by":{"0":"40"}},{"t":"case","label":"Korte v. Sebelius","cite":"735 F.3d 654","y":2013,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/735/654/","by":{"0":"7, 32"}},{"t":"case","label":"Universidad Central de Bayamon v. NLRB","cite":"793 F.2d 383","y":1985,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/793/383/","by":{"0":"33"}},{"t":"case","label":"Lee v. Sixth Mount Zion Baptist Church","cite":"903 F.3d 113","y":2018,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/903/113/","by":{"0":"40","2":"14, 30","3":"14, 30","4":"38"}},{"t":"case","label":"McCarthy v. Fuller","cite":"714 F.3d 971","y":2013,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/714/971/","by":{"0":"31"}},{"t":"case","label":"McClure v. Salvation Army","cite":"460 F.2d 553","y":1972,"url":"https://www.courtlistener.com/c/F.2d/460/553/","op":1,"by":{"0":"6, 34","5":"18"}},{"t":"case","label":"McKelvey v. Pierce","cite":"800 A.2d 840","y":2002,"court":"N.J.","url":"https://www.courtlistener.com/c/A.2d/800/840/","by":{"0":"35"}},{"t":"case","label":"Miller v. Catholic Diocese of Great Falls","cite":"728 P.2d 794","y":1986,"court":"Mont.","url":"https://www.courtlistener.com/c/P.2d/728/794/","by":{"0":"35","5":"24"}},{"t":"case","label":"Music v. United Methodist Church","cite":"864 S.W.2d 286","y":1993,"court":"Ky.","url":"https://www.courtlistener.com/c/S.W.2d/864/286/","by":{"0":"35"}},{"t":"case","label":"NLRB v. Catholic Bishop of Chicago","cite":"440 U.S. 490","y":1979,"id":"1978/77-752","sc":1,"sum":"Schools operated by a church to teach both religious and secular subjects are not within the jurisdiction granted by the National Labor Relations Act, and the NLRB was therefore without authority to issue the orders against respondents.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"11","2":"13, 30","3":"13, 30","4":"31","5":"11, 25"}},{"t":"case","label":"Pardue v. Center City Consortium Sch.","cite":"875 A.2d 669","y":2005,"court":"D.C.","url":"https://www.courtlistener.com/c/A.2d/875/669/","by":{"0":"35","5":"9"}},{"t":"case","label":"viii Paul v. Watchtower Bible & Tract Soc’y of N.Y., Inc.","cite":"819 F.2d 875","y":1987,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/819/875/","op":1,"by":{"0":"31, 32"}},{"t":"case","label":"Petruska v. Gannon Univ.","cite":"462 F.3d 294","y":2006,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/462/294/","op":1,"by":{"0":"7, 35, 40","5":"5"}},{"t":"case","label":"Pfeil v. St. Matthews Evangelical Lutheran Church","cite":"877 N.W.2d 528","y":2016,"court":"Minn.","url":"https://www.courtlistener.com/c/N.W.2d/877/528/","by":{"0":"32"}},{"t":"case","label":"Pierce v. Iowa-Missouri Conference","cite":"534 N.W.2d 425","y":1995,"court":"Iowa","url":"https://www.courtlistener.com/c/N.W.2d/534/425/","by":{"0":"35"}},{"t":"case","label":"Puri v. Khalsa","cite":"844 F.3d 1152","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/844/1152/","by":{"0":"31"}},{"t":"case","label":"Rayburn v. Gen. Conf. of Seventh-Day Adventists","cite":"772 F.2d 1164","y":1985,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/772/1164/","op":3,"ar":5,"by":{"0":"7, 25, 35","4":"19, 23, 24, 28","5":"4, 7, 8, 17"}},{"t":"case","label":"Rweyemamu v. Cote","cite":"520 F.3d 198","y":2008,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/520/198/","sum":"Noting it sufficed that “Father Justinian [wa]s an ordained priest of the Roman Catholic Church”.","sumSrc":"brief:0","by":{"0":"7, 50"}},{"t":"case","label":"Sawyer v. Brandon","cite":"825 So. 2d 26","y":2002,"court":"Miss.","url":"https://www.courtlistener.com/c/So.%202d/825/26/","by":{"0":"35"}},{"t":"case","label":"Serbian E. Orthodox Diocese v. Milivojevich","cite":"426 U.S. 696","y":1976,"id":"1975/75-292","sc":1,"op":2,"sum":"During the course of a protracted dispute over the control of the Serbian Eastern Orthodox Diocese for the United States and Canada, the Holy Assembly of Bishops and the Holy Synod of the Serbian Orthodox Church (Mother Church) suspended and ultimately removed and defrocked the Bishop, respondent Dionisije, and appointed petitioner Firmilian as Administrator of the Diocese, which the Mother Church then reorganized …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27-28","2":"13","3":"13","4":"28"}},{"t":"case","label":"ix Smith v. Calvary Christian Church","cite":"614 N.W.2d 590","y":2000,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W.2d/614/590/","by":{"0":"31-32"}},{"t":"case","label":"Sterlinski v. Catholic Bishop of Chicago","cite":"934 F.3d 568","y":2019,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/934/568/","by":{"0":"41","1":"10"}},{"t":"case","label":"Temple Emanuel of Newton v. Massachusetts Comm’n Against Discrimination","cite":"975 N.E.2d 433","y":2012,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E.2d/975/433/","by":{"0":"40","5":"3, 9, 15"}},{"t":"case","label":"United States v. Ballard","cite":"322 U.S. 78","y":1944,"id":"scdb/1943-132","sc":1,"sum":"Upon an indictment charging use of the mails to defraud, and conspiracy so to do, respondents were convicted in the District Court. The indictment charged a scheme to defraud through representations-involving respondents' religious doctrines or beliefs-which were alleged to be false and known by the respondents to be false. Holding that the District Court had restricted the jury to the issue -of respondents' good …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"United States v. Seeger","cite":"380 U.S. 163","y":1965,"id":"1964/50","sc":1,"sum":"The Court held that a person can have conscientious objector status based on a belief that has a similar position in that person's life to the belief in God.","sumSrc":"Oyez","by":{"0":"31","4":"50"}},{"t":"case","label":"Watson v. Jones","cite":"80 U.S. 679","y":1871,"id":"scdb/1871-152","sc":1,"sum":"1. When in courts of concurrent jurisdiction, the pendency of a suit in one is relied on to defeat a second suit in the other, the identity cf the parties, of the case made, and of the relief sought, should be such that if the first suit had been decided it could be pleaded in bar as a former adjudication.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"28, 30","5":"9"}},{"t":"case","label":"Westbrook v. Penley","cite":"231 S.W.3d 389","y":2007,"court":"Tex.","url":"https://www.courtlistener.com/c/S.W.3d/231/389/","by":{"0":"30, 35"}},{"t":"case","label":"Williams v. Episcopal Diocese of Mass.","cite":"766 N.E.2d 820","y":2002,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E.2d/766/820/","by":{"0":"35"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"0":"passim","1":"3, 4, 5, 6, 15, 16, 19"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"5"}},{"t":"usc","label":"29 U.S.C. § 621","url":"https://www.law.cornell.edu/uscode/text/29/621","stext":{"head":"§621. Congressional statement of findings and purpose","paras":[[0,"(a) The Congress hereby finds and declares that—"],[1,"(1) in the face of rising productivity and affluence, older workers find themselves disadvantaged in their efforts to retain employment, and especially to regain employment when displaced from jobs;"],[1,"(2) the setting of arbitrary age limits regardless of potential for job performance has become a common practice, and certain otherwise desirable practices may work to the disadvantage of older persons;"],[1,"(3) the incidence of unemployment, especially long-term unemployment with resultant deterioration of skill, morale, and employer acceptability is, relative to the younger ages, high among older workers; their numbers are great and growing; and their employment problems grave;"],[1,"(4) the existence in industries affecting commerce, of arbitrary discrimination in employment because of age, burdens commerce and the free flow of goods in commerce."],[0,"(b) It is therefore the purpose of this chapter to promote employment of older persons based on their ability rather than age; to prohibit arbitrary age discrimination in employment; to help employers and workers find ways of meeting problems arising from the impact of age on employment."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/621?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§621. Congressional statement of findings and purpose","tname":"Labor","by":{"0":"6","2":"5","3":"5","4":"14"}},{"t":"usc","label":"42 U.S.C. § 2000bb","url":"https://www.law.cornell.edu/uscode/text/42/2000bb","stext":{"head":"§2000bb. Congressional findings and declaration of purposes","paras":[[0,"(a) Findings"],[0,"The Congress finds that—"],[1,"(1) the framers of the Constitution, recognizing free exercise of religion as an unalienable right, secured its protection in the First Amendment to the Constitution;"],[1,"(2) laws \"neutral\" toward religion may burden religious exercise as surely as laws intended to interfere with religious exercise;"],[1,"(3) governments should not substantially burden religious exercise without compelling justification;"],[1,"(4) in Employment Division v. Smith, 494 U.S. 872 (1990) the Supreme Court virtually eliminated the requirement that the government justify burdens on religious exercise imposed by laws neutral toward religion; and"],[1,"(5) the compelling interest test as set forth in prior Federal court rulings is a workable test for striking sensible balances between religious liberty and competing prior governmental interests."],[0,"(b) Purposes"],[0,"The purposes of this chapter are—"],[1,"(1) to restore the compelling interest test as set forth in Sherbert v. Verner, 374 U.S. 398 (1963) and Wisconsin v. Yoder, 406 U.S. 205 (1972) and to guarantee its application in all cases where free exercise of religion is substantially burdened; and"],[1,"(2) to provide a claim or defense to persons whose religious exercise is substantially burdened by government."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000bb?type=usc&year=mostrecent&link-type=html"},"head":"§2000bb. Congressional findings and declaration of purposes","tname":"The Public Health and Welfare","by":{"0":"32","4":"53"}},{"t":"usc","label":"42 U.S.C. § 12101","url":"https://www.law.cornell.edu/uscode/text/42/12101","stext":{"head":"§12101. Findings and purpose","paras":[[0,"(a) Findings"],[0,"The Congress finds that—"],[1,"(1) physical or mental disabilities in no way diminish a person's right to fully participate in all aspects of society, yet many people with physical or mental disabilities have been precluded from doing so because of discrimination; others who have a record of a disability or are regarded as having a disability also have been subjected to discrimination;"],[1,"(2) historically, society has tended to isolate and segregate individuals with disabilities, and, despite some improvements, such forms of discrimination against individuals with disabilities continue to be a serious and pervasive social problem;"],[1,"(3) discrimination against individuals with disabilities persists in such critical areas as employment, housing, public accommodations, education, transportation, communication, recreation, institutionalization, health services, voting, and access to public services;"],[1,"(4) unlike individuals who have experienced discrimination on the basis of race, color, sex, national origin, religion, or age, individuals who have experienced discrimination on the basis of disability have often had no legal recourse to redress such discrimination;"],[1,"(5) individuals with disabilities continually encounter various forms of discrimination, including outright intentional exclusion, the discriminatory effects of architectural, transportation, and communication barriers, overprotective rules and policies, failure to make modifications to existing facilities and practices, exclusionary qualification standards and criteria, segregation, and relegation to lesser services, programs, activities, benefits, jobs, or other opportunities;"],[1,"(6) census data, national polls, and other studies have documented that people with disabilities, as a group, occupy an inferior status in our society, and are severely disadvantaged socially, vocationally, economically, and educationally;"],[1,"(7) the Nation's proper goals regarding individuals with disabilities are to assure equality of opportunity, full participation, independent living, and economic self-sufficiency for such individuals; and"],[1,"(8) the continuing existence of unfair and unnecessary discrimination and prejudice denies people with disabilities the opportunity to compete on an equal basis and to pursue those opportunities for which our free society is justifiably famous, and costs the United States billions of dollars in unnecessary expenses resulting from dependency and nonproductivity."],[0,"(b) Purpose"],[0,"It is the purpose of this chapter—"],[1,"(1) to provide a clear and comprehensive national mandate for the elimination of discrimination against individuals with disabilities;"],[1,"(2) to provide clear, strong, consistent, enforceable standards addressing discrimination against individuals with disabilities;"],[1,"(3) to ensure that the Federal Government plays a central role in enforcing the standards established in this chapter on behalf of individuals with disabilities; and"],[1,"(4) to invoke the sweep of congressional authority, including the power to enforce the fourteenth amendment and to regulate commerce, in order to address the major areas of discrimination faced day-to-day by people with disabilities."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/12101?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§12101. Findings and purpose","tname":"The Public Health and Welfare","by":{"0":"6","2":"6","3":"6","4":"10"}},{"t":"case","label":"Biel v. St. James Sch.","cite":"911 F.3d 603","y":2018,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/911/603/","op":18,"by":{"1":"11, 12, 16"}},{"t":"case","label":"Biel v. St. James Sch.","cite":"926 F.3d 1238","y":2019,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/926/1238/","op":2,"by":{"1":"19"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"1":"4"}},{"t":"case","label":"Dunn v. Ray","cite":"139 S. Ct. 661","y":2019,"url":"https://www.courtlistener.com/c/S.%20Ct./139/661/","sc":1,"by":{"1":"15"}},{"t":"case","label":"Duquesne Univ. of the Holy Spirit v. NLRB, ___ F.3d ___","cite":"2020 WL 425053","y":2020,"court":"D.C. Cir. Jan. 28","by":{"1":"11"}},{"t":"case","label":"EEOC v. Catholic Univ. of Am.","cite":"83 F.3d 455","y":1996,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/83/455/","by":{"1":"10"}},{"t":"case","label":"Epperson v. Ark.","cite":"393 U.S. 97","y":1968,"id":"1968/7","sc":1,"sum":"The Court found that a statute forbidding the teaching of human evolution violated the Establishment Clause of the First Amendment.","sumSrc":"Oyez","by":{"1":"15"}},{"t":"case","label":"Larson v. Valente","cite":"456 U.S. 228","y":1982,"id":"1981/80-1666","sc":1,"sum":"The Court held that the fifty percent rule clearly distinguished between denominations and created denominational preferences within the law, and it did not serve a compelling government interest. The Court also held that the Act failed the three-part test established in Lemon v. Kurtzman by fostering the government entanglement in religion.","sumSrc":"Oyez","by":{"1":"15, 16","5":"13"}},{"t":"case","label":"McDaniel v. Paty","cite":"435 U.S. 618","y":1978,"id":"1977/76-1427","sc":1,"op":1,"sum":"The Court held that the statute made the ability to exercise civil rights conditional on the surrender of religious rights and therefore violated the First Amendment protection of the free exercise of religion as applied to the states by the Fourteenth Amendment.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"Morrissey-Berru v. Our Lady of Guadalupe Sch.","cite":"769 F. App’x 460","y":2019,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/769/460/","by":{"1":"12, 16"}},{"t":"case","label":"Trinity Lutheran Church of Columbia, Inc. v. Comer","cite":"137 S. Ct. 2012","y":2017,"id":"2016/15-577","sc":1,"sum":"The Court determined that the exclusion of churches from an otherwise neutral and secular aid program violates the First Amendment’s guarantee of free exercise of religion.","sumSrc":"Oyez","by":{"1":"13","2":"34","3":"34"}},{"t":"case","label":"Trump v. Hawaii","cite":"138 S. Ct. 2392","y":2018,"id":"2017/17-965","sc":1,"sum":"The Court held that President Donald Trump’s Proclamation restricting travel and immigration to the US from certain countries (“travel ban”) does not violate the president’s statutory authority or the Establishment Clause of the Constitution. The Court was also asked, but did not decide, whether a global injunction barring enforcement of parts of the Proclamation is impermissibly overbroad.","sumSrc":"Oyez","by":{"1":"15"}},{"t":"case","label":"Walz v. Tax Comm’n of City of N.Y.","cite":"397 U.S. 664","y":1970,"id":"1969/135","sc":1,"sum":"In a 7-to-1 decision, the Court held that the exemptions did not violate the Establishment Clause. The Court held that the purpose of the exemptions was to neither advance nor inhibit religion; no one particular church or religious group had been singled out to receive tax exempt status.","sumSrc":"Oyez","by":{"1":"4"}},{"t":"case","label":"Sterlinski v. Catholic Bishop of Chicago","cite":"943 F.3d 568","y":2019,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/943/568/","by":{"2":"14, 20, 28","3":"14, 20, 28"}},{"t":"usc","label":"42 U.S.C. § 2000e","url":"https://www.law.cornell.edu/uscode/text/42/2000e","stext":{"head":"§2000e. Definitions","paras":[[0,"For the purposes of this subchapter—"],[1,"(a) The term \"person\" includes one or more individuals, governments, governmental agencies, political subdivisions, labor unions, partnerships, associations, corporations, legal representatives, mutual companies, joint-stock companies, trusts, unincorporated organizations, trustees, trustees in cases under title 11, or receivers."],[1,"(b) The term \"employer\" means a person engaged in an industry affecting commerce who has fifteen or more employees for each working day in each of twenty or more calendar weeks in the current or preceding calendar year, and any agent of such a person, but such term does not include (1) the United States, a corporation wholly owned by the Government of the United States, an Indian tribe, or any department or agency of the District of Columbia subject by statute to procedures of the competitive service (as defined in section 2102 of title 5), or (2) a bona fide private membership club (other than a labor organization) which is exempt from taxation under section 501(c) of title 26, except that during the first year after March 24, 1972, persons having fewer than twenty-five employees (and their agents) shall not be considered employers."],[1,"(c) The term \"employment agency\" means any person regularly undertaking with or without compensation to procure employees for an employer or to procure for employees opportunities to work for an employer and includes an agent of such a person."],[1,"(d) The term \"labor organization\" means a labor organization engaged in an industry affecting commerce, and any agent of such an organization, and includes any organization of any kind, any agency, or employee representation committee, group, association, or plan so engaged in which employees participate and which exists for the purpose, in whole or in part, of dealing with employers concerning grievances, labor disputes, wages, rates of pay, hours, or other terms or conditions of employment, and any conference, general committee, joint or system board, or joint council so engaged which is subordinate to a national or international labor organization."],[1,"(e) A labor organization shall be deemed to be engaged in an industry affecting commerce if (1) it maintains or operates a hiring hall or hiring office which procures employees for an employer or procures for employees opportunities to work for an employer, or (2) the number of its members (or, where it is a labor organization composed of other labor organizations or their representatives, if the aggregate number of the members of such other labor organization) is (A) twenty-five or more during the first year after March 24, 1972, or (B) fifteen or more thereafter, and such labor organization—"],[2,"(1) is the certified representative of employees under the provisions of the National Labor Relations Act, as amended [29 U.S.C. 151 et seq.], or the Railway Labor Act, as amended [45 U.S.C. 151 et seq.];"],[2,"(2) although not certified, is a national or international labor organization or a local labor organization recognized or acting as the representative of employees of an employer or employers engaged in an industry affecting commerce; or"],[2,"(3) has chartered a local labor organization or subsidiary body which is representing or actively seeking to represent employees of employers within the meaning of paragraph (1) or (2); or"],[2,"(4) has been chartered by a labor organization representing or actively seeking to represent employees within the meaning of paragraph (1) or (2) as the local or subordinate body through which such employees may enjoy membership or become affiliated with such labor organization; or"],[2,"(5) is a conference, general committee, joint or system board, or joint council subordinate to a national or international labor organization, which includes a labor organization engaged in an industry affecting commerce within the meaning of any of the preceding paragraphs of this subsection."],[1,"(f) The term \"employee\" means an individual employed by an employer, except that the term \"employee\" shall not include any person elected to public office in any State or political subdivision of any State by the qualified voters thereof, or any person chosen by such officer to be on such officer's personal staff, or an appointee on the policy making level or an immediate adviser with respect to the exercise of the constitutional or legal powers of the office. The exemption set forth in the preceding sentence shall not include employees subject to the civil service laws of a State government, governmental agency or political subdivision. With respect to employment in a foreign country, such term includes an individual who is a citizen of the United States."],[1,"(g) The term \"commerce\" means trade, traffic, commerce, transportation, transmission, or communication among the several States; or between a State and any place outside thereof; or within the District of Columbia, or a possession of the United States; or between points in the same State but through a point outside thereof."],[1,"(h) The term \"industry affecting commerce\" means any activity, business, or industry in commerce or in which a labor dispute would hinder or obstruct commerce or the free flow of commerce and includes any activity or industry \"affecting commerce\" within the meaning of the Labor-Management Reporting and Disclosure Act of 1959 [29 U.S.C. 401 et seq.], and further includes any governmental industry, business, or activity."],[1,"(i) The term \"State\" includes a State of the United States, the District of Columbia, Puerto Rico, the Virgin Islands, American Samoa, Guam, Wake Island, the Canal Zone, and Outer Continental Shelf lands defined in the Outer Continental Shelf Lands Act [43 U.S.C. 1331 et seq.]."],[1,"(j) The term \"religion\" includes all aspects of religious observance and practice, as well as belief, unless an employer demonstrates that he is unable to reasonably accommodate to an employee's or prospective employee's religious observance or practice without undue hardship on the conduct of the employer's business."],[1,"(k) The terms \"because of sex\" or \"on the basis of sex\" include, but are not limited to, because of or on the basis of pregnancy, childbirth, or related medical conditions; and women affected by pregnancy, childbirth, or related medical conditions shall be treated the same for all employment-related purposes, including receipt of benefits under fringe benefit programs, as other persons not so affected but similar in their ability or inability to work, and nothing in section 2000e–2(h) of this title shall be interpreted to permit otherwise. This subsection shall not require an employer to pay for health insurance benefits for abortion, except where the life of the mother would be endangered if the fetus were carried to term, or except where medical complications have arisen from an abortion: Provided, That nothing herein shall preclude an employer from providing abortion benefits or otherwise affect bargaining agreements in regard to abortion."],[1,"(l) The term \"complaining party\" means the Commission, the Attorney General, or a person who may bring an action or proceeding under this subchapter."],[1,"(m) The term \"demonstrates\" means meets the burdens of production and persuasion."],[1,"(n) The term \"respondent\" means an employer, employment agency, labor organization, joint labor-management committee controlling apprenticeship or other training or retraining program, including an on-the-job training program, or Federal entity subject to section 2000e–16 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e?type=usc&year=mostrecent&link-type=html"},"op":3,"head":"§2000e. Definitions","tname":"The Public Health and Welfare","by":{"2":"29","3":"29","4":"3"}},{"t":"usc","label":"42 U.S.C. § 2000e-1","url":"https://www.law.cornell.edu/uscode/text/42/2000e-1","subs":["(a)"],"stext":{"head":"§2000e–1. Exemption","paras":[[0,"(a) Inapplicability of subchapter to certain aliens and employees of religious entities"],[0,"This subchapter shall not apply to an employer with respect to the employment of aliens outside any State, or to a religious corporation, association, educational institution, or society with respect to the employment of individuals of a particular religion to perform work connected with the carrying on by such corporation, association, educational institution, or society of its activities."],[0,"(b) Compliance with statute as violative of foreign law"],[0,"It shall not be unlawful under section 2000e–2 or 2000e–3 of this title for an employer (or a corporation controlled by an employer), labor organization, employment agency, or joint labor-management committee controlling apprenticeship or other training or retraining (including on-the-job training programs) to take any action otherwise prohibited by such section, with respect to an employee in a workplace in a foreign country if compliance with such section would cause such employer (or such corporation), such organization, such agency, or such committee to violate the law of the foreign country in which such workplace is located."],[0,"(c) Control of corporation incorporated in foreign country"],[0,"(1) If an employer controls a corporation whose place of incorporation is a foreign country, any practice prohibited by section 2000e–2 or 2000e–3 of this title engaged in by such corporation shall be presumed to be engaged in by such employer."],[0,"(2) Sections 2000e–2 and 2000e–3 of this title shall not apply with respect to the foreign operations of an employer that is a foreign person not controlled by an American employer."],[0,"(3) For purposes of this subsection, the determination of whether an employer controls a corporation shall be based on—"],[1,"(A) the interrelation of operations;"],[1,"(B) the common management;"],[1,"(C) the centralized control of labor relations; and"],[1,"(D) the common ownership or financial control,"],[0,"of the employer and the corporation."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-1?type=usc&year=mostrecent&link-type=html"},"head":"§2000e–1. Exemption","tname":"The Public Health and Welfare","by":{"2":"29","3":"29","4":"3"}},{"t":"usc","label":"42 U.S.C. § 2000e-2","url":"https://www.law.cornell.edu/uscode/text/42/2000e-2","subs":["(e)"],"stext":{"head":"§2000e–2. Unlawful employment practices","paras":[[0,"(a) Employer practices"],[0,"It shall be an unlawful employment practice for an employer—"],[1,"(1) to fail or refuse to hire or to discharge any individual, or otherwise to discriminate against any individual with respect to his compensation, terms, conditions, or privileges of employment, because of such individual's race, color, religion, sex, or national origin; or"],[1,"(2) to limit, segregate, or classify his employees or applicants for employment in any way which would deprive or tend to deprive any individual of employment opportunities or otherwise adversely affect his status as an employee, because of such individual's race, color, religion, sex, or national origin."],[0,"(b) Employment agency practices"],[0,"It shall be an unlawful employment practice for an employment agency to fail or refuse to refer for employment, or otherwise to discriminate against, any individual because of his race, color, religion, sex, or national origin, or to classify or refer for employment any individual on the basis of his race, color, religion, sex, or national origin."],[0,"(c) Labor organization practices"],[0,"It shall be an unlawful employment practice for a labor organization—"],[1,"(1) to exclude or to expel from its membership, or otherwise to discriminate against, any individual because of his race, color, religion, sex, or national origin;"],[1,"(2) to limit, segregate, or classify its membership or applicants for membership, or to classify or fail or refuse to refer for employment any individual, in any way which would deprive or tend to deprive any individual of employment opportunities, or would limit such employment opportunities or otherwise adversely affect his status as an employee or as an applicant for employment, because of such individual's race, color, religion, sex, or national origin; or"],[1,"(3) to cause or attempt to cause an employer to discriminate against an individual in violation of this section."],[0,"(d) Training programs"],[0,"It shall be an unlawful employment practice for any employer, labor organization, or joint labor-management committee controlling apprenticeship or other training or retraining, including on-the-job training programs to discriminate against any individual because of his race, color, religion, sex, or national origin in admission to, or employment in, any program established to provide apprenticeship or other training."],[0,"(e) Businesses or enterprises with personnel qualified on basis of religion, sex, or national origin; educational institutions with personnel of particular religion"],[0,"Notwithstanding any other provision of this subchapter, (1) it shall not be an unlawful employment practice for an employer to hire and employ employees, for an employment agency to classify, or refer for employment any individual, for a labor organization to classify its membership or to classify or refer for employment any individual, or for an employer, labor organization, or joint labor-management committee controlling apprenticeship or other training or retraining programs to admit or employ any individual in any such program, on the basis of his religion, sex, or national origin in those certain instances where religion, sex, or national origin is a bona fide occupational qualification reasonably necessary to the normal operation of that particular business or enterprise, and (2) it shall not be an unlawful employment practice for a school, college, university, or other educational institution or institution of learning to hire and employ employees of a particular religion if such school, college, university, or other educational institution or institution of learning is, in whole or in substantial part, owned, supported, controlled, or managed by a particular religion or by a particular religious corporation, association, or society, or if the curriculum of such school, college, university, or other educational institution or institution of learning is directed toward the propagation of a particular religion."],[0,"(f) Members of Communist Party or Communist-action or Communist-front organizations"],[0,"As used in this subchapter, the phrase \"unlawful employment practice\" shall not be deemed to include any action or measure taken by an employer, labor organization, joint labor-management committee, or employment agency with respect to an individual who is a member of the Communist Party of the United States or of any other organization required to register as a Communist-action or Communist-front organization by final order of the Subversive Activities Control Board pursuant to the Subversive Activities Control Act of 1950 [50 U.S.C. 781 et seq.]."],[0,"(g) National security"],[0,"Notwithstanding any other provision of this subchapter, it shall not be an unlawful employment practice for an employer to fail or refuse to hire and employ any individual for any position, for an employer to discharge any individual from any position, or for an employment agency to fail or refuse to refer any individual for employment in any position, or for a labor organization to fail or refuse to refer any individual for employment in any position, if—"],[1,"(1) the occupancy of such position, or access to the premises in or upon which any part of the duties of such position is performed or is to be performed, is subject to any requirement imposed in the interest of the national security of the United States under any security program in effect pursuant to or administered under any statute of the United States or any Executive order of the President; and"],[1,"(2) such individual has not fulfilled or has ceased to fulfill that requirement."],[0,"(h) Seniority or merit system; quantity or quality of production; ability tests; compensation based on sex and authorized by minimum wage provisions"],[0,"Notwithstanding any other provision of this subchapter, it shall not be an unlawful employment practice for an employer to apply different standards of compensation, or different terms, conditions, or privileges of employment pursuant to a bona fide seniority or merit system, or a system which measures earnings by quantity or quality of production or to employees who work in different locations, provided that such differences are not the result of an intention to discriminate because of race, color, religion, sex, or national origin, nor shall it be an unlawful employment practice for an employer to give and to act upon the results of any professionally developed ability test provided that such test, its administration or action upon the results is not designed, intended or used to discriminate because of race, color, religion, sex or national origin. It shall not be an unlawful employment practice under this subchapter for any employer to differentiate upon the basis of sex in determining the amount of the wages or compensation paid or to be paid to employees of such employer if such differentiation is authorized by the provisions of section 206(d) of title 29."],[0,"(i) Businesses or enterprises extending preferential treatment to Indians"],[0,"Nothing contained in this subchapter shall apply to any business or enterprise on or near an Indian reservation with respect to any publicly announced employment practice of such business or enterprise under which a preferential treatment is given to any individual because he is an Indian living on or near a reservation."],[0,"(j) Preferential treatment not to be granted on account of existing number or percentage imbalance"],[0,"Nothing contained in this subchapter shall be interpreted to require any employer, employment agency, labor organization, or joint labor-management committee subject to this subchapter to grant preferential treatment to any individual or to any group because of the race, color, religion, sex, or national origin of such individual or group on account of an imbalance which may exist with respect to the total number or percentage of persons of any race, color, religion, sex, or national origin employed by any employer, referred or classified for employment by any employment agency or labor organization, admitted to membership or classified by any labor organization, or admitted to, or employed in, any apprenticeship or other training program, in comparison with the total number or percentage of persons of such race, color, religion, sex, or national origin in any community, State, section, or other area, or in the available work force in any community, State, section, or other area."],[0,"(k) Burden of proof in disparate impact cases"],[0,"(1)(A) An unlawful employment practice based on disparate impact is established under this subchapter only if—"],[1,"(i) a complaining party demonstrates that a respondent uses a particular employment practice that causes a disparate impact on the basis of race, color, religion, sex, or national origin and the respondent fails to demonstrate that the challenged practice is job related for the position in question and consistent with business necessity; or"],[1,"(ii) the complaining party makes the demonstration described in subparagraph (C) with respect to an alternative employment practice and the respondent refuses to adopt such alternative employment practice."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/2000e-2?type=usc&year=mostrecent&link-type=html"},"head":"§2000e–2. Unlawful employment practices","tname":"The Public Health and Welfare","by":{"2":"29","3":"29"}},{"t":"usc","label":"29 U.S.C. § 151","url":"https://www.law.cornell.edu/uscode/text/29/151","stext":{"head":"§151. Findings and declaration of policy","paras":[[0,"The denial by some employers of the right of employees to organize and the refusal by some employers to accept the procedure of collective bargaining lead to strikes and other forms of industrial strife or unrest, which have the intent or the necessary effect of burdening or obstructing commerce by (a) impairing the efficiency, safety, or operation of the instrumentalities of commerce; (b) occurring in the current of commerce; (c) materially affecting, restraining, or controlling the flow of raw materials or manufactured or processed goods from or into the channels of commerce, or the prices of such materials or goods in commerce; or (d) causing diminution of employment and wages in such volume as substantially to impair or disrupt the market for goods flowing from or into the channels of commerce."],[0,"The inequality of bargaining power between employees who do not possess full freedom of association or actual liberty of contract, and employers who are organized in the corporate or other forms of ownership association substantially burdens and affects the flow of commerce, and tends to aggravate recurrent business depressions, by depressing wage rates and the purchasing power of wage earners in industry and by preventing the stabilization of competitive wage rates and working conditions within and between industries."],[0,"Experience has proved that protection by law of the right of employees to organize and bargain collectively safeguards commerce from injury, impairment, or interruption, and promotes the flow of commerce by removing certain recognized sources of industrial strife and unrest, by encouraging practices fundamental to the friendly adjustment of industrial disputes arising out of differences as to wages, hours, or other working conditions, and by restoring equality of bargaining power between employers and employees."],[0,"Experience has further demonstrated that certain practices by some labor organizations, their officers, and members have the intent or the necessary effect of burdening or obstructing commerce by preventing the free flow of goods in such commerce through strikes and other forms of industrial unrest or through concerted activities which impair the interest of the public in the free flow of such commerce. The elimination of such practices is a necessary condition to the assurance of the rights herein guaranteed."],[0,"It is hereby declared to be the policy of the United States to eliminate the causes of certain substantial obstructions to the free flow of commerce and to mitigate and eliminate these obstructions when they have occurred by encouraging the practice and procedure of collective bargaining and by protecting the exercise by workers of full freedom of association, self-organization, and designation of representatives of their own choosing, for the purpose of negotiating the terms and conditions of their employment or other mutual aid or protection."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/29/151?type=usc&year=mostrecent&link-type=html"},"head":"§151. Findings and declaration of policy","tname":"Labor","by":{"2":"13","3":"13"}},{"t":"case","label":"Agostini v. Felton","cite":"521 U.S. 203","y":1997,"id":"1996/96-552","sc":1,"sum":"The Court held that there was no evidence to support its former presumption that the entrance of public school teachers into parochial schools will inevitably lead to the indoctrination of state-sponsored religion.","sumSrc":"Oyez","by":{"4":"21"}},{"t":"case","label":"Alicea-Hernandez v. Catholic Bishop of Chi.","cite":"320 F.3d 698","y":2003,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/320/698/","ar":1,"by":{"4":"38","5":"15, 18"}},{"t":"case","label":"Ballaban v. Bloomington Jewish Community, Inc.","cite":"982 N.E.2d 329","y":2013,"court":"Ind. App.","url":"https://www.courtlistener.com/c/N.E.2d/982/329/","by":{"4":"39"}},{"t":"case","label":"Barrett v. Fontbonne Acad.","cite":"2015 WL 9682042","y":2015,"court":"Mass. Super. Ct. Dec. 16","by":{"4":"32"}},{"t":"case","label":"Bob Jones Univ. v. United States","cite":"461 U.S. 574","y":1983,"id":"1982/81-3","sc":1,"op":1,"sum":"The Court found that the IRS was correct in its decision to revoke the tax-exempt status of Bob Jones University and the Goldsboro Christian School. These institutions did not meet the requirement by providing \"beneficial and stabilizing influences in community life\" to be supported by taxpayers with a special tax status. The schools could not meet this requirement due to their discriminatory policies.","sumSrc":"Oyez","by":{"4":"53"}},{"t":"case","label":"Boy Scouts of Am. v. Dale","cite":"530 U.S. 640","y":2000,"id":"1999/99-699","sc":1,"sum":"The Court held that the Boy Scouts of America banning openly homosexual members was constitutional under the First Amendment.","sumSrc":"Oyez","by":{"4":"52"}},{"t":"case","label":"Braun v. St. Pius X Par.","cite":"827 F. Supp. 2d 1312","y":2011,"court":"N.D. Okla.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/827/1312/","by":{"4":"21"}},{"t":"case","label":"Burwell v. Hobby Lobby Stores, Inc.","cite":"573 U.S. 682","y":2014,"id":"2013/13-354","sc":1,"sum":"The Court decided that the Affordable Care Act's requirement of for-profit corporations to supply its employees with contraceptives that go against the owners' beliefs is unconstitutional under the Religious Freedom Restoration Act of 1993.","sumSrc":"Oyez","by":{"4":"53"}},{"t":"case","label":"Cline v. Catholic Diocese of Toledo","cite":"206 F.3d 651","y":2000,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/206/651/","by":{"4":"4","5":"11"}},{"t":"case","label":"Combs v. Cent. Tex. Annual Conference of United Methodist Church","cite":"173 F.3d 343","y":1999,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/173/343/","by":{"4":"19"}},{"t":"case","label":"Davis v. Balt. Hebrew Congregation","cite":"985 F. Supp. 2d 701","y":2013,"court":"D. Md.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/985/701/","sum":"Rejecting argument that such persons are ministers.","sumSrc":"brief:4","by":{"4":"34","5":"17"}},{"t":"case","label":"Dayton Christian Schs., Inc. v. Ohio Civil Rights Comm’n","cite":"766 F.2d 932","y":1985,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/766/932/","by":{"4":"25, 46, 47"}},{"t":"case","label":"DeMarco v. Holy Cross High Sch.","cite":"4 F.3d 166","y":1993,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/4/166/","by":{"4":"4, 5, 50","5":"11"}},{"t":"case","label":"Dias v. Archdiocese of Cincinnati","cite":"2013 WL 360355","y":2013,"court":"S.D. Ohio. Jan. 30","by":{"4":"31"}},{"t":"case","label":"Dole v. Shenandoah Baptist Church","cite":"899 F.2d 1389","y":1990,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/899/1389/","op":1,"by":{"4":"4, 5, 6","5":"11"}},{"t":"case","label":"Dolter v. Wahlert High Sch.","cite":"483 F. Supp. 266","y":1980,"court":"N.D. Iowa","url":"https://www.courtlistener.com/c/F.%20Supp./483/266/","by":{"4":"4","5":"11"}},{"t":"case","label":"EEOC v. Fremont Christian Sch.","cite":"781 F.2d 1362","y":1986,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/781/1362/","op":1,"by":{"4":"4, 5","5":"11"}},{"t":"case","label":"EEOC v. Hosanna-Tabor Evangelical Lutheran Church & Sch.","cite":"597 F.3d 769","y":2010,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/597/769/","by":{"4":"6"}},{"t":"case","label":"EEOC v. Miss. College","cite":"626 F.2d 477","y":1980,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/626/477/","op":1,"by":{"4":"4, 5, 31","5":"11"}},{"t":"case","label":"EEOC v. Pac. Press Publ’g Ass’n","cite":"676 F.2d 1272","y":1982,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/676/1272/","sum":"Rejecting argument that editorial secretary was minister.","sumSrc":"brief:4","by":{"4":"33"}},{"t":"case","label":"EEOC v. Sw. Baptist Theological Seminary","cite":"651 F.2d 277","y":1981,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/651/277/","op":1,"sum":"Rejecting seminary’s argument “that all of its [administrative and support staff] serve a ministerial function”.","sumSrc":"brief:4","by":{"4":"24, 35"}},{"t":"case","label":"EEOC v. Tree of Life Christian Schs.","cite":"751 F. Supp. 700","y":1990,"court":"S.D. Ohio","url":"https://www.courtlistener.com/c/F.%20Supp./751/700/","by":{"4":"4, 5","5":"11"}},{"t":"case","label":"Geary v. Visitation of the Blessed Virgin Mary Parish Sch.","cite":"7 F.3d 324","y":1993,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/7/324/","op":1,"by":{"4":"4, 5, 50, 51","5":"11"}},{"t":"case","label":"Green v. Brennan","cite":"136 S. Ct. 1769","y":2016,"id":"2015/14-613","sc":1,"sum":"The Court held that the 45-day period in which an employee must file a constructive discharge claim under federal employment discrimination law begins to run on the date the employee resigns.","sumSrc":"Oyez","by":{"4":"7"}},{"t":"case","label":"Guinan v. Roman Catholic Archdiocese of Indianapolis","cite":"42 F. Supp. 2d 849","y":1998,"court":"S.D. Ind.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/42/849/","by":{"4":"4","5":"11"}},{"t":"case","label":"Hall v. Baptist Mem’l Health Care Corp.","cite":"215 F.3d 618","y":2000,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/215/618/","by":{"4":"51"}},{"t":"case","label":"Hall v. Salvation Army","cite":"261 N.Y. 110","y":1933,"url":"https://www.courtlistener.com/c/N.Y./261/110/","by":{"4":"34"}},{"t":"case","label":"Hankins v. Lyght","cite":"441 F.3d 96","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/441/96/","op":2,"by":{"4":"4","5":"5"}},{"t":"case","label":"Hernandez v. C.I.R.","cite":"490 U.S. 680","y":1989,"id":"1988/87-963","sc":1,"ar":1,"sum":"Payments made to the Church's branch churches for auditing and training services are not deductible charitable contributions under § 170.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"50"}},{"t":"case","label":"Herx v. Diocese of Ft. Wayne-South Bend Inc.","cite":"48 F. Supp. 3d 1168","y":2014,"court":"N.D. Ind.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/48/1168/","by":{"4":"31"}},{"t":"case","label":"Hurley v. Irish-Am. Gay, Lesbian, & Bisexual Grp.","cite":"515 U.S. 557","y":1995,"id":"1994/94-749","sc":1,"sum":"A unanimous court held that the State Court's ruling to require private citizens who organize a parade to include a group expressing a message that the organizers do not wish to convey violates the First Amendment by making private speech subordinate to the public accommodation requirement.","sumSrc":"Oyez","by":{"4":"52"}},{"t":"case","label":"Kennedy v. Bremerton Sch. Dist.","cite":"869 F.3d 813","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/869/813/","by":{"4":"32"}},{"t":"case","label":"Locke v. Davey","cite":"540 U.S. 712","y":2004,"id":"2003/02-1315","sc":1,"op":1,"sum":"The Court ruled that a state does not violate the First Amendment's free exercise clause when it funds secular college majors but excludes devotional theology majors.","sumSrc":"Oyez","by":{"4":"48"}},{"t":"case","label":"Meek v. Pittenger","cite":"421 U.S. 349","y":1975,"id":"1974/73-1765","sc":1,"sum":"Act 194 and all but the textbook loan provisions of Act 195 violate the Establishment Clause of the First Amendment as made applicable to the States by the Fourteenth. Pp. 359-372; 388. 374 F. Supp. 639, affirmed in part, reversed in part. MR. JusTicE STnwART delivered the opinion of the Court with respect to Parts I, II, IV, and V, finding:","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"30, 31"}},{"t":"case","label":"Mitchell v. Pilgrim Holiness Church Corp.","cite":"210 F.2d 879","y":1954,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/210/879/","sum":"Rejecting First Amendment defense regarding employees at church-owned printing plant who produced, packaged, and distributed religious books, magazines, and leaflets.","sumSrc":"brief:4","by":{"4":"33"}},{"t":"case","label":"New York v. Cathedral Acad.","cite":"434 U.S. 125","y":1977,"id":"1977/76-616","sc":1,"sum":"A three-judge District Court issued a judgment (later affirmed by this Court) declaring unconstitutional a New York statute (1970 N. Y. Laws, ch. 138) that authorized reimbursement to nonpublic schools for statemandated recordkeeping and testing services, and permanently enjoinmg any payments under the Act, including reimbursement for expenses that such schools had already incurred in the last half of the 1971-1972 …","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"30"}},{"t":"case","label":"Ohio Civil Rights Commission v. Dayton Christian Schools, Inc.","cite":"477 U.S. 619","y":1986,"id":"1985/85-488","sc":1,"sum":"The Court held that federal courts should abstain from adjudicating civil state proceedings in which important state interests are involved.","sumSrc":"Oyez","by":{"4":"passim","5":"10"}},{"t":"case","label":"Our Lady’s Inn v. City of St. Louis","cite":"349 F. Supp. 3d 805","y":2018,"court":"E.D. Mo.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/349/805/","by":{"4":"53"}},{"t":"case","label":"Presbyterian Church v. Mary Elizabeth Blue Hull Mem’l Presbyterian Church","cite":"393 U.S. 440","y":1969,"id":"1968/71","sc":1,"op":2,"sum":"The Court held that the civil courts do not have the ability to determine title to church property on the basis of the civil court’s interpretation of the church doctrine.","sumSrc":"Oyez","by":{"4":"21"}},{"t":"case","label":"Redhead v. Conf. of Seventh-Day Adventists","cite":"440 F. Supp. 2d 211","y":2006,"court":"E.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/440/211/","by":{"4":"4","5":"11"}},{"t":"case","label":"Richardson v. Nw. Christian Univ.","cite":"242 F. Supp. 3d 1132","y":2017,"court":"D. Or.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/242/1132/","by":{"4":"31","5":"7"}},{"t":"case","label":"Roberts v. U.S. Jaycees","cite":"468 U.S. 609","y":1984,"id":"1983/83-724","sc":1,"sum":"The Court held that the Jaycees chapters lacked \"the distinctive characteristics that might afford constitutional protection to the decision of its members to exclude women.\" The Court reasoned that making women full members would not impose any serious burdens on the male members' freedom of expressive association.","sumSrc":"Oyez","by":{"4":"51, 52, 53","5":"5"}},{"t":"case","label":"Sch. Dist. of Abington Twp. v. Schempp","cite":"374 U.S. 203","y":1963,"id":"1962/142","sc":1,"sum":"The Court found that mandatory daily Bible readings and prayer in Pennsylvania public schools violated the First Amendment rights of its students.","sumSrc":"Oyez","by":{"4":"47"}},{"t":"case","label":"Scharon v. St. Luke’s Episcopal Presbyterian Hosps.","cite":"929 F.2d 360","y":1991,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/929/360/","op":2,"by":{"4":"20, 49"}},{"t":"case","label":"Schleicher v. Salvation Army","cite":"518 F.3d 472","y":2008,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/518/472/","by":{"4":"38"}},{"t":"case","label":"Skrzypczak v. Roman Catholic Diocese of Tulsa","cite":"611 F.3d 1238","y":2010,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/611/1238/","by":{"4":"37"}},{"t":"case","label":"Smith v. Raleigh Dist. of N.C. Conf. of United Methodist Church","cite":"63 F. Supp. 2d 694","y":1999,"court":"E.D.N.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/63/694/","by":{"4":"35"}},{"t":"case","label":"Su v. Stephen S. Wise Temple","cite":"32 Cal. App. 5th 1159","y":2019,"url":"https://www.courtlistener.com/c/Cal.%20App.%205th/32/1159/","op":2,"ar":1,"by":{"4":"38"}},{"t":"case","label":"Vigars v. Valley Christian Ctr.","cite":"805 F. Supp. 802","y":1992,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp./805/802/","by":{"4":"4","5":"11"}},{"t":"usc","label":"18 U.S.C. § 1513","url":"https://www.law.cornell.edu/uscode/text/18/1513","by":{"4":"38"}},{"t":"usc","label":"29 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/29/201","by":{"4":"38"}},{"t":"usc","label":"29 U.S.C. § 623","url":"https://www.law.cornell.edu/uscode/text/29/623","by":{"4":"50"}},{"t":"usc","label":"29 U.S.C. § 660","url":"https://www.law.cornell.edu/uscode/text/29/660","by":{"4":"38"}},{"t":"usc","label":"42 U.S.C. § 12112","url":"https://www.law.cornell.edu/uscode/text/42/12112","stext":{"head":"§12112. Discrimination","paras":[[0,"(a) General rule"],[0,"No covered entity shall discriminate against a qualified individual on the basis of disability in regard to job application procedures, the hiring, advancement, or discharge of employees, employee compensation, job training, and other terms, conditions, and privileges of employment."],[0,"(b) Construction"],[0,"As used in subsection (a), the term \"discriminate against a qualified individual on the basis of disability\" includes—"],[1,"(1) limiting, segregating, or classifying a job applicant or employee in a way that adversely affects the opportunities or status of such applicant or employee because of the disability of such applicant or employee;"],[1,"(2) participating in a contractual or other arrangement or relationship that has the effect of subjecting a covered entity's qualified applicant or employee with a disability to the discrimination prohibited by this subchapter (such relationship includes a relationship with an employment or referral agency, labor union, an organization providing fringe benefits to an employee of the covered entity, or an organization providing training and apprenticeship programs);"],[1,"(3) utilizing standards, criteria, or methods of administration—"],[2,"(A) that have the effect of discrimination on the basis of disability; or"],[2,"(B) that perpetuate the discrimination of others who are subject to common administrative control;"],[1,"(4) excluding or otherwise denying equal jobs or benefits to a qualified individual because of the known disability of an individual with whom the qualified individual is known to have a relationship or association;"],[1,"(5)(A) not making reasonable accommodations to the known physical or mental limitations of an otherwise qualified individual with a disability who is an applicant or employee, unless such covered entity can demonstrate that the accommodation would impose an undue hardship on the operation of the business of such covered entity; or"],[1,"(B) denying employment opportunities to a job applicant or employee who is an otherwise qualified individual with a disability, if such denial is based on the need of such covered entity to make reasonable accommodation to the physical or mental impairments of the employee or applicant;"],[1,"(6) using qualification standards, employment tests or other selection criteria that screen out or tend to screen out an individual with a disability or a class of individuals with disabilities unless the standard, test or other selection criteria, as used by the covered entity, is shown to be job-related for the position in question and is consistent with business necessity; and"],[1,"(7) failing to select and administer tests concerning employment in the most effective manner to ensure that, when such test is administered to a job applicant or employee who has a disability that impairs sensory, manual, or speaking skills, such test results accurately reflect the skills, aptitude, or whatever other factor of such applicant or employee that such test purports to measure, rather than reflecting the impaired sensory, manual, or speaking skills of such employee or applicant (except where such skills are the factors that the test purports to measure)."],[0,"(c) Covered entities in foreign countries"],[0,"(1) In general"],[1,"It shall not be unlawful under this section for a covered entity to take any action that constitutes discrimination under this section with respect to an employee in a workplace in a foreign country if compliance with this section would cause such covered entity to violate the law of the foreign country in which such workplace is located."],[0,"(2) Control of corporation"],[0,"(A) Presumption"],[2,"If an employer controls a corporation whose place of incorporation is a foreign country, any practice that constitutes discrimination under this section and is engaged in by such corporation shall be presumed to be engaged in by such employer."],[0,"(B) Exception"],[2,"This section shall not apply with respect to the foreign operations of an employer that is a foreign person not controlled by an American employer."],[0,"(C) Determination"],[2,"For purposes of this paragraph, the determination of whether an employer controls a corporation shall be based on—"],[3,"(i) the interrelation of operations;"],[3,"(ii) the common management;"],[3,"(iii) the centralized control of labor relations; and"],[3,"(iv) the common ownership or financial control,"],[2,"of the employer and the corporation."],[0,"(d) Medical examinations and inquiries"],[0,"(1) In general"],[1,"The prohibition against discrimination as referred to in subsection (a) shall include medical examinations and inquiries."],[0,"(2) Preemployment"],[0,"(A) Prohibited examination or inquiry"],[2,"Except as provided in paragraph (3), a covered entity shall not conduct a medical examination or make inquiries of a job applicant as to whether such applicant is an individual with a disability or as to the nature or severity of such disability."],[0,"(B) Acceptable inquiry"],[2,"A covered entity may make preemployment inquiries into the ability of an applicant to perform job-related functions."],[0,"(3) Employment entrance examination"],[1,"A covered entity may require a medical examination after an offer of employment has been made to a job applicant and prior to the commencement of the employment duties of such applicant, and may condition an offer of employment on the results of such examination, if—"],[2,"(A) all entering employees are subjected to such an examination regardless of disability;"],[2,"(B) information obtained regarding the medical condition or history of the applicant is collected and maintained on separate forms and in separate medical files and is treated as a confidential medical record, except that—"],[3,"(i) supervisors and managers may be informed regarding necessary restrictions on the work or duties of the employee and necessary accommodations;"],[3,"(ii) first aid and safety personnel may be informed, when appropriate, if the disability might require emergency treatment; and"],[3,"(iii) government officials investigating compliance with this chapter shall be provided relevant information on request; and"],[2,"(C) the results of such examination are used only in accordance with this subchapter."],[0,"(4) Examination and inquiry"],[0,"(A) Prohibited examinations and inquiries"],[2,"A covered entity shall not require a medical examination and shall not make inquiries of an employee as to whether such employee is an individual with a disability or as to the nature or severity of the disability, unless such examination or inquiry is shown to be job-related and consistent with business necessity."],[0,"(B) Acceptable examinations and inquiries"],[2,"A covered entity may conduct voluntary medical examinations, including voluntary medical histories, which are part of an employee health program available to employees at that work site. A covered entity may make inquiries into the ability of an employee to perform job-related functions."],[0,"(C) Requirement"],[2,"Information obtained under subparagraph (B) regarding the medical condition or history of any employee are subject to the requirements of subparagraphs (B) and (C) of paragraph (3)."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/12112?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§12112. Discrimination","tname":"The Public Health and Welfare","by":{"4":"50"}},{"t":"usc","label":"42 U.S.C. § 12113","url":"https://www.law.cornell.edu/uscode/text/42/12113","stext":{"head":"§12113. Defenses","paras":[[0,"(a) In general"],[0,"It may be a defense to a charge of discrimination under this chapter that an alleged application of qualification standards, tests, or selection criteria that screen out or tend to screen out or otherwise deny a job or benefit to an individual with a disability has been shown to be job-related and consistent with business necessity, and such performance cannot be accomplished by reasonable accommodation, as required under this subchapter."],[0,"(b) Qualification standards"],[0,"The term \"qualification standards\" may include a requirement that an individual shall not pose a direct threat to the health or safety of other individuals in the workplace."],[0,"(c) Qualification standards and tests related to uncorrected vision"],[0,"Notwithstanding section 12102(4)(E)(ii) of this title, a covered entity shall not use qualification standards, employment tests, or other selection criteria based on an individual's uncorrected vision unless the standard, test, or other selection criteria, as used by the covered entity, is shown to be job-related for the position in question and consistent with business necessity."],[0,"(d) Religious entities"],[0,"(1) In general"],[1,"This subchapter shall not prohibit a religious corporation, association, educational institution, or society from giving preference in employment to individuals of a particular religion to perform work connected with the carrying on by such corporation, association, educational institution, or society of its activities."],[0,"(2) Religious tenets requirement"],[1,"Under this subchapter, a religious organization may require that all applicants and employees conform to the religious tenets of such organization."],[0,"(e) List of infectious and communicable diseases"],[0,"(1) In general"],[1,"The Secretary of Health and Human Services, not later than 6 months after July 26, 1990, shall—"],[2,"(A) review all infectious and communicable diseases which may be transmitted through handling the food supply;"],[2,"(B) publish a list of infectious and communicable diseases which are transmitted through handling the food supply;"],[2,"(C) publish the methods by which such diseases are transmitted; and"],[2,"(D) widely disseminate such information regarding the list of diseases and their modes of transmissability 1 to the general public."],[1,"Such list shall be updated annually."],[0,"(2) Applications"],[1,"In any case in which an individual has an infectious or communicable disease that is transmitted to others through the handling of food, that is included on the list developed by the Secretary of Health and Human Services under paragraph (1), and which cannot be eliminated by reasonable accommodation, a covered entity may refuse to assign or continue to assign such individual to a job involving food handling."],[0,"(3) Construction"],[1,"Nothing in this chapter shall be construed to preempt, modify, or amend any State, county, or local law, ordinance, or regulation applicable to food handling which is designed to protect the public health from individuals who pose a significant risk to the health or safety of others, which cannot be eliminated by reasonable accommodation, pursuant to the list of infectious or communicable diseases and the modes of transmissability 1 published by the Secretary of Health and Human Services."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/12113?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§12113. Defenses","tname":"The Public Health and Welfare","by":{"4":"50"}},{"t":"usc","label":"42 U.S.C. § 1985","url":"https://www.law.cornell.edu/uscode/text/42/1985","by":{"4":"38"}},{"t":"case","label":"Agency for Int’l Dev. v. AOSI, Inc.","cite":"570 U.S. 205","y":2013,"id":"2012/12-10","sc":1,"sum":"The Court held that it was a violation of the First Amendment to withhold funding from non-government organizations if they did not institute an anti-prostitution policy.","sumSrc":"Oyez","by":{"5":"16-17"}},{"t":"case","label":"Bose Corp. v. Consumers Union","cite":"466 U.S. 485","y":1984,"id":"1983/82-1246","sc":1,"sum":"The Court held that while the record revealed that the article's author mistakenly described the sound path of Bose speakers, he did not do so with actual malice.","sumSrc":"Oyez","by":{"5":"19"}},{"t":"case","label":"Bryce v. Episcopal Church","cite":"289 F.3d 648","y":2002,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/289/648/","by":{"5":"25"}},{"t":"case","label":"Cantwell v. Connecticut","cite":"310 U.S. 296","y":1940,"id":"1940-1955/310us296","sc":1,"sum":"The Court found that it was a violation of the First Amendment to restrict solicitation of religious speech.","sumSrc":"Oyez","by":{"5":"16"}},{"t":"case","label":"Ciurleo v. St. Regis Parish","cite":"214 F. Supp. 3d 647","y":2016,"court":"E.D. Mich.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/214/647/","by":{"5":"9, 15"}},{"t":"case","label":"Clapper v. Chesapeake Conference of Seventh-day Adventists","cite":"166 F.3d 1208","y":1998,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/166/1208/","by":{"5":"8-9"}},{"t":"case","label":"Curl v. Beltsville Adventist School","cite":"2016 WL 4382686","y":2016,"court":"D. Md.","by":{"5":"10, 15"}},{"t":"case","label":"Dayton Christian Schools v. Ohio Civil Rights Comm’n","cite":"578 F. Supp. 1004","y":1984,"court":"S.D. Ohio","url":"https://www.courtlistener.com/c/F.%20Supp./578/1004/","by":{"5":"10"}},{"t":"case","label":"Dias v. Archdiocese of Cincinnati","cite":"2012 WL 1068165","y":2012,"court":"S.D. Ohio","by":{"5":"7"}},{"t":"case","label":"EEOC v. Abercrombie & Fitch Stores, Inc.","cite":"575 U.S. 768","y":2015,"id":"2014/14-86","sc":1,"sum":"The Court held that an employer may be held liable under Title VII of the Civil Rights Act if an applicant can show that her need for an accommodation was a motivating factor in the employer’s decision not to hire her.","sumSrc":"Oyez","by":{"5":"6"}},{"t":"case","label":"EEOC v. Roman Catholic Diocese of Raleigh","cite":"213 F.3d 795","y":2000,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/213/795/","op":1,"by":{"5":"passim"}},{"t":"case","label":"Grussgott v. Milwaukee Jewish Day School, Inc.","cite":"882 F.3d 655","y":2018,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/882/655/","ar":1,"by":{"5":"9, 14, 15, 20"}},{"t":"case","label":"Hutson v. Concord Christian School","cite":"2019 WL 5699235","y":2019,"court":"E.D. Tenn.","by":{"5":"9-10"}},{"t":"case","label":"Lemon v. Kurtzman","cite":"403 U.S. 602","y":1971,"id":"1970/89","sc":1,"op":1,"sum":"The Court found that Pennsylvania and Rhode Island statutes granting salary supplements to teachers at \"church-related educational institutions\" was unconstitutional for violating the Establishment Clause of the First Amendment. The case established the Lemon Test for determining if the government is becoming too involved in religious activities.","sumSrc":"Oyez","by":{"5":"11"}},{"t":"case","label":"Local 1545 v. Vincent","cite":"286 F.2d 127","y":1960,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/286/127/","by":{"5":"17"}},{"t":"case","label":"Patton v. United States","cite":"281 U.S. 276","y":1930,"id":"scdb/1929-043","sc":1,"sum":"1. After the commencement of a trial in a federal court before a jury of twelve men upon an indictment charging a crime, punishment for which may involve a penitentiary sentence, if one juror becomes incapacitated and unable to proceed further with his work as a juror, the defendant and the Government, through its official representative in charge of the case, may consent to the trial's proceeding to a finality with …","sumSrc":"Syllabus (U.S. Reports)","by":{"5":"5"}},{"t":"case","label":"Sherbert v. Verner","cite":"374 U.S. 398","y":1963,"id":"1962/526","sc":1,"sum":"The Court found that the denial of unemployment compensation because of religious practices violated the First and Fourteenth Amendments.","sumSrc":"Oyez","by":{"5":"11"}},{"t":"case","label":"Stately v. Indian Cmty. Sch. of Milwaukee","cite":"351 F. Supp. 2d 858","y":2004,"court":"E.D. Wis.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/351/858/","by":{"5":"9"}},{"t":"case","label":"Stepek v. Doe","cite":"910 N.E.2d 655","y":2009,"court":"Ill. App. Ct.","url":"https://www.courtlistener.com/c/N.E.2d/910/655/","by":{"5":"18"}},{"t":"case","label":"vii Wisconsin v. Yoder","cite":"406 U.S. 205","y":1972,"id":"1971/70-110","sc":1,"sum":"The Court held that the First Amendment prohibited the state of Wisconsin to require Amish children to attend public school beyond the eighth grade.","sumSrc":"Oyez","by":{"5":"6, 7"}},{"t":"case","label":"Yellowbear v. Lampert","cite":"741 F.3d 48","y":2014,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/741/48/","by":{"5":"6"}}]};